function guidePage(index){const g=GUIDE[index]||GUIDE[0];return `<div class="shell page-route">${headerHtml()}<section class="pagehead guide-head"><div class="eyebrow">The Bali Guide</div><h1>${g[0]}</h1><p>${g[1]}</p></section><article class="card guide-content">${guideContent(index)}</article>${guideLinks(index)}<section class="section guide-back"><button class="btn light" onclick="backTo('bali')">← Back to Bali Guide</button></section></div>${navHtml()}`}
function guideContent(i){const blocks=[
`<h3>Travel documents</h3><ul><li>Check your passport well before departure. The source guide recommends allowing at least six months validity for Indonesia and keeping the passport in good condition.</li><li>Keep a digital passport copy in secure cloud/email storage and one physical copy separate from the original.</li><li>Save your travel insurance certificate, emergency assistance number, flight confirmations and accommodation details so they can be accessed offline.</li></ul><h3>Money & cards before you leave</h3><ul><li>Let your bank know you are travelling if your provider recommends it.</li><li>Bring more than one payment method. A physical travel card plus a backup bank card is useful if one is blocked or lost.</li><li>Set up Apple Pay or Google Pay before travel if you use it, and keep some access to cash for arrival.</li></ul><h3>Packing for Bali</h3><ul><li>Light, breathable clothing works best in the heat and humidity. Pack comfortable footwear, swimwear, sun protection and a compact rain layer.</li><li>Bring regular medicines in their original packaging and keep essential medication in your carry-on.</li><li>Indonesia commonly uses two-pin round plugs. A universal adaptor and power bank are useful.</li></ul><h3>Phone & digital prep</h3><ul><li>WhatsApp is widely used by drivers, villas, restaurants and local services.</li><li>Download transport, banking/travel-card and translation apps before you fly so logins and verification can be completed at home.</li><li>Consider roaming, an eSIM or a local SIM depending on your phone and plan.</li></ul><h3>Entry requirements</h3><p>Use the Bali Ready area for the current e-VOA/visa, Bali Tourist Levy and All Indonesia declaration links. Entry rules can change, so confirm critical information again shortly before departure.</p>`,
`<h3>Before landing</h3><ul><li>Have your passport and any required entry QR codes or confirmations easy to reach, not buried in checked luggage.</li><li>Keep your accommodation address saved on your phone in case it is requested.</li><li>If you have booked an airport transfer, screenshot the driver name, contact number and meeting instructions.</li></ul><h3>Immigration</h3><ul><li>Follow airport signage to the appropriate immigration counter or eligible e-gate.</li><li>Processing time varies. Busy arrival banks can make queues significantly longer.</li><li>Answer questions clearly and keep your onward/return travel details accessible if requested.</li></ul><h3>Baggage collection</h3><ul><li>Check the baggage screen for your carousel and stay in the baggage area until your bag has arrived.</li><li>If a bag does not arrive, report it before leaving the baggage claim area and keep the baggage tag supplied at check-in.</li><li>Porter assistance may be available; clarify any fee before accepting help.</li></ul><h3>Customs & exit</h3><ul><li>Complete any required declaration and follow the signs through customs.</li><li>The arrivals hall can be busy with transport offers, SIM providers and people waiting for passengers.</li><li>You do not need to accept the first transport offer. Use your pre-arranged driver, ride-hailing app or an official taxi option.</li></ul><h3>Airport transport</h3><p>For this trip you can book Made from the Travel tab. Your confirmed flight, sign name, destination, drinks order and cash total will be stored in My Plans.</p>`,
`<h3>Private drivers</h3><ul><li>A reliable private driver is useful for airport transfers, day trips and longer journeys.</li><li>Save a good driver’s WhatsApp number. The source guide recommends building a relationship with drivers you trust rather than finding someone new every time.</li><li>For street-arranged transport, confirm the destination and price before leaving.</li></ul><h3>Grab & Gojek</h3><ul><li>Ride-hailing apps provide the pickup point and fare in the app, which makes them convenient for many everyday trips.</li><li>Confirm the driver and booking details before getting in. For motorbike rides, use a helmet and consider your travel-insurance conditions.</li><li>Some venues or local zones have specific pickup points. Follow the app or venue instructions rather than standing in traffic.</li></ul><h3>Blue Bird taxis</h3><ul><li>Blue Bird is a well-known metered taxi option. You can hail an available taxi or book through its app.</li><li>When using any street taxi, confirm that the meter is being used or agree the fare before the trip.</li></ul><h3>Bali traffic</h3><ul><li>Distance on a map does not equal travel time. Short trips around Seminyak, Canggu and other busy areas can take much longer than expected.</li><li>Allow extra time for dinner reservations, airport travel, ceremonies and peak periods.</li></ul><h3>Walking</h3><ul><li>Footpaths may be uneven, interrupted or shared with driveways and scooters. Watch your footing, especially at night and after rain.</li><li>For longer trips or roads with heavy traffic, a car or reputable taxi may be more comfortable.</li></ul><h3>Boats & island transfers</h3><ul><li>Fast-boat schedules can change because of sea and weather conditions. Delays and cancellations do happen.</li><li>Avoid tight same-day flight connections after an island transfer; build in buffer time where possible.</li></ul>`,
`<h3>Currency</h3><ul><li>Indonesia uses Indonesian Rupiah (IDR). The live converter on the Bali tab is an indicative rate; banks, cards and money changers may differ.</li><li>Large rupiah numbers are normal. Count the zeros carefully and check the amount on payment terminals before approving.</li></ul><h3>Cash vs card</h3><ul><li>Cards are common in larger venues, but cash is still useful for smaller shops, drivers, markets, tips and cash-on-day bookings.</li><li>Keep a backup card separate from your everyday wallet.</li></ul><h3>ATMs</h3><ul><li>Use reputable bank ATMs or machines in established locations where possible.</li><li>Shield your PIN and take your card, cash and receipt before leaving.</li><li>If a machine looks damaged or tampered with, use another ATM.</li></ul><h3>Money changers</h3><ul><li>Use established, clearly signed money changers. Check the rate and recount the money yourself before leaving the counter.</li><li>Be cautious with rates that appear dramatically better than everywhere else.</li></ul><h3>Everyday shopping</h3><ul><li>Convenience stores and supermarkets are easy places to buy water, snacks, toiletries, electrolytes and basic travel supplies.</li><li>The source guide references common chains such as Indomaret, Circle K, Pepito, Bintang Supermarket and Coco Supermarket.</li></ul><h3>Pharmacies</h3><ul><li>Pharmacies are widely available. If you need medication advice, speak with a pharmacist or medical professional rather than relying on assumptions about local brand names.</li></ul>`,
`<h3>Water</h3><ul><li>Do not drink untreated tap water. Use sealed bottled water or properly filtered drinking water.</li><li>Use the same drinking water for brushing teeth if that is what your accommodation recommends.</li><li>Keep hydrated in the heat; dehydration can arrive quickly when alcohol, sun and pool time are combined.</li></ul><h3>Ice & drinks</h3><ul><li>Established hotels, restaurants and bars commonly use commercially produced ice. If you are unsure, ask the venue.</li><li>For locally produced alcohol, buy from reputable venues and avoid unlabelled or suspicious spirits.</li></ul><h3>Restaurants & cafés</h3><ul><li>Bali has everything from small local warungs to international restaurants. Busy, well-run venues with good recent reviews are a useful starting point.</li><li>If you have a serious food allergy, communicate it clearly and remember that cross-contamination can still occur.</li></ul><h3>Street food</h3><ul><li>Use the same judgement you would anywhere: look for good turnover, clean handling and food that is cooked and served hot where appropriate.</li><li>If something looks or smells wrong, skip it.</li></ul><h3>If you feel unwell</h3><ul><li>Rest and focus on fluids. Seek medical advice if symptoms are severe, persistent or you are struggling to stay hydrated.</li><li>Use Dr Ari or Mobile Medicine from Quick Help if you want local medical support.</li><li>Contact your travel insurer when you need medical care that may involve a claim.</li></ul>`,
`<h3>Medical support</h3><ul><li>Keep your travel-insurance assistance number and policy details saved offline.</li><li>Doctors and mobile medical services can often attend villas and hotels. Quick Help contains the contacts selected for this trip.</li><li>For urgent or serious symptoms, use an emergency department or urgent medical service.</li></ul><h3>Heat & dehydration</h3><ul><li>Bali is hot and humid. Drink water regularly and take breaks in shade or air-conditioning.</li><li>Electrolyte drinks can be useful after heavy sweating, long outdoor days or stomach illness.</li></ul><h3>Sun</h3><ul><li>UV exposure can be high even when it is cloudy. Sunscreen, a hat, shade and sensible time in direct sun matter.</li></ul><h3>Mosquitoes</h3><ul><li>Use repellent, particularly around dawn/dusk and areas with gardens or still water.</li><li>Close screens/doors where practical and follow accommodation advice.</li></ul><h3>Animals</h3><ul><li>Do not approach unfamiliar street dogs, cats or monkeys. Bites and scratches need prompt cleaning and medical advice.</li><li>Keep food and loose belongings away from monkeys in areas where they are common.</li></ul><h3>Medication</h3><ul><li>Carry your essential medicines in original packaging and bring enough for the trip plus a reasonable buffer.</li><li>If you need a replacement medicine in Bali, speak to a qualified pharmacist or doctor so the active ingredient and dose are confirmed.</li></ul>`,
`<h3>Indonesian law</h3><ul><li>Bali is part of Indonesia and Indonesian laws apply. Drug laws are particularly strict.</li><li>Visa conditions and driving/licensing requirements matter even when enforcement looks different from home.</li></ul><h3>Temples & ceremonies</h3><ul><li>Follow local signage and instructions, dress appropriately where requested and avoid disrupting ceremonies for photos.</li><li>Daily offerings are often placed on pavements and entrances. Step around them rather than on them.</li></ul><h3>Scams & pressure</h3><ul><li>Confirm prices and services before proceeding. Do not feel pressured to accept transport, exchange money or make a purchase.</li><li>Use reputable booking channels and read recent reviews for higher-value activities.</li></ul><h3>Night-time safety</h3><ul><li>Use normal travel awareness: keep valuables secure, avoid isolated shortcuts and use reputable transport when needed.</li><li>Keep your phone charged enough to access maps, transport and your accommodation details.</li></ul><h3>Scooters</h3><ul><li>Experience, licensing, helmets and insurance conditions all matter. A short distance does not remove the risk.</li><li>If you are not confident riding, use a driver, taxi, Grab or Gojek car instead.</li></ul><h3>Ocean & adventure activities</h3><ul><li>Sea conditions can change quickly. Follow local warnings, lifeguards and reputable operator instructions.</li><li>For adventure activities, use well-reviewed operators, wear the provided safety equipment and check what your travel insurance covers.</li></ul>`,
`<h3>Choosing where to stay</h3><ul><li>Pick your area based on how you actually want to spend your days. Traffic can shape the experience more than distance on the map suggests.</li><li>Hotels, private villas and villa/resort hybrids offer different levels of service, privacy and facilities.</li></ul><h3>Private villas</h3><ul><li>Ask about check-in method, housekeeping, pool care, laundry, transport and who to contact after hours.</li><li>Save the exact address and pin location; small lanes can be difficult for first-time drivers to find.</li></ul><h3>Longer bookings</h3><ul><li>For longer stays, ask whether housekeeping, linen changes, electricity, breakfast, maintenance and airport transfers are included.</li><li>Read recent reviews rather than relying only on photos.</li></ul><h3>Working remotely</h3><ul><li>Confirm Wi-Fi quality and backup options before relying on a villa for work.</li><li>A local/eSIM data connection can be useful as a backup during outages.</li></ul><h3>Wellness & activities</h3><ul><li>Popular restaurants, wellness appointments and day trips can book out in busy periods, so reserve important plans ahead.</li><li>Leave some unplanned time. Bali traffic and weather make an overly tight itinerary harder to enjoy.</li></ul>`,
`<h3>Use WhatsApp</h3><ul><li>Many Bali businesses organise bookings, directions and changes through WhatsApp. Save important contacts with useful labels.</li><li>Send your live location when it genuinely helps a driver find you, then stop sharing when it is no longer needed.</li></ul><h3>Screenshot the important stuff</h3><ul><li>Save your villa address, flight information, booking confirmations, QR codes and driver instructions before leaving Wi-Fi.</li></ul><h3>Hydration kit</h3><ul><li>Keep drinking water and electrolytes in your villa and carry water on longer outings.</li><li>A small day bag with sunscreen, repellent, tissues, power bank and cash covers most everyday problems.</li></ul><h3>Laundry & delivery</h3><ul><li>Laundry pickup/delivery is inexpensive and saves holiday time. Quick Help includes the selected service.</li><li>Food and everyday items can often be delivered through local apps depending on your location.</li></ul><h3>Bookings</h3><ul><li>Recent reviews and direct confirmation are valuable. Message a venue if you are unsure about opening hours, dress codes or a booking.</li><li>For popular restaurants and wellness venues, booking ahead is easier than trying to solve it at the door.</li></ul><h3>Maps & addresses</h3><ul><li>Save a Google Maps pin as well as the written address. Bali street names and villa lanes can be confusing.</li><li>If a driver looks unsure, show the pin rather than repeatedly reading the address aloud.</li></ul><h3>Keep plans flexible</h3><ul><li>Tropical rain, ceremonies, traffic and sea conditions can change a day. Build space into the plan rather than scheduling every minute.</li></ul>`
];return blocks[i]||blocks[0]}
function guideLinks(i){const maps={
0:[['Bali Ready','#/ready'],['Smartraveller — Indonesia','https://www.smartraveller.gov.au/destinations/asia/indonesia']],
1:[['Book Made airport pickup','#/travel'],['All Indonesia','https://allindonesia.imigrasi.go.id/']],
2:[['Download Grab','app:grab'],['Download Gojek','app:gojek'],['Download Bluebird','app:bluebird']],
3:[['Travel card options','modal:cards'],['Live AUD ↔ IDR converter','#/bali']],
4:[['WhatsApp Dr Ari',`https://wa.me/${CFG.drAri}`],['Quick Help','#/bali']],
5:[['WhatsApp Dr Ari',`https://wa.me/${CFG.drAri}`],['Find a hospital','maps:Hospital']],
6:[['Smartraveller — Indonesia','https://www.smartraveller.gov.au/destinations/asia/indonesia'],['Find transport','#/bali']],
7:[['Booking.com — Bali','https://www.booking.com/searchresults.html?ss=Bali%2C%20Indonesia'],['Airbnb — Bali','https://www.airbnb.com/s/Bali--Indonesia/homes'],['Chandra Villas',VILLA_URL]],
8:[['Google Translate','https://translate.google.com/'],['Quick Help','#/bali']]
};const items=maps[i]||[];return `<section class="section"><article class="card learn-more"><div class="meta">Learn more</div><h3>Useful links</h3><p>Open the service you need and come straight back to the guide when you’re done.</p><div class="link-grid">${items.map(([label,url])=>{if(url.startsWith('app:'))return `<button class="btn light" onclick="openTransportApp('${url.slice(4)}')">${label}</button>`;if(url.startsWith('modal:'))return `<button class="btn light" onclick="openModal('${url.slice(6)}')">${label}</button>`;if(url.startsWith('maps:'))return `<button class="btn light" onclick="findNear('${url.slice(5)}')">${label}</button>`;if(url.startsWith('#/'))return `<button class="btn light" onclick="go('${url.slice(2)}')">${label}</button>`;return `<a class="btn light" href="${url}" target="_blank" rel="noopener">${label}</a>`}).join('')}</div></article></section>`}
function openTransportApp(which){const android=/Android/i.test(navigator.userAgent);const links={grab:{ios:'https://apps.apple.com/app/grab-taxi-ride-food-delivery/id647268330',android:'https://play.google.com/store/apps/details?id=com.grabtaxi.passenger'},gojek:{ios:'https://apps.apple.com/app/gojek/id944875099',android:'https://play.google.com/store/apps/details?id=com.gojek.app'},bluebird:{ios:'https://apps.apple.com/app/mybluebird-taxi-booking/id470812653',android:'https://play.google.com/store/apps/details?id=com.seatech.bluebird'}};const x=links[which];if(x)window.open(android?x.android:x.ios,'_blank')}
function profilePage(){return `<div class="shell">${headerHtml()}<section class="pagehead"><div class="eyebrow">Your space</div><h1>My Profile</h1><p>Your profile, bookings and trip plans.</p></section><article class="card profile-card"><div class="avatar">${APP.profile.photo?`<img src="${APP.profile.photo}" alt="Profile photo" style="width:100%;height:100%;object-fit:cover">`:'☺'}</div><div><h3>${esc(APP.profile.name||'Guest')}</h3><p>${APP.profile.email?esc(APP.profile.email):'Add your email for confirmations and receipts.'}</p></div></article>
<section class="section"><article class="card"><div class="form"><div class="field"><label>Name</label><input id="profileName" value="${attr(APP.profile.name||'')}"></div><div class="field"><label>Email address</label><input id="profileEmail" type="email" value="${attr(APP.profile.email||'')}" placeholder="you@example.com"></div><div class="field"><label>4-digit PIN</label><input id="profilePin" inputmode="numeric" maxlength="4" value="${attr(APP.profile.pin||'')}" placeholder="1234"></div><div class="field"><label>Profile photo</label><button class="btn light" onclick="chooseProfilePhoto()">Add / change photo</button><input id="profilePhoto" type="file" accept="image/*" hidden></div><button class="btn full" onclick="saveProfile()">Save profile</button></div></article></section>
<section class="section"><div class="section-head"><div><h2 class="section-title">My Plans</h2><p class="section-sub">Everything you’ve RSVP’d, booked or purchased.</p></div></div>${APP.plans.length?APP.plans.map((p,i)=>`<article class="card plan" style="margin-bottom:12px"><div><span class="status-badge">${planStatus(p)}</span><h3>${esc(p.title)}</h3><p>${esc(p.meta||'')}</p>${p.total?`<strong>${esc(p.total)}</strong>`:''}</div><div class="actions"><button class="btn light" onclick="cancelPlan(${i})">Cancel</button></div></article>`).join(''):`<article class="card"><p>Nothing booked yet.</p></article>`}</section></div>${navHtml()}`}
function recoveryPage(){return `<div class="recovery-shell"><div class="shell"><div class="recovery-top"><button class="aus-btn" onclick="backTo('home')">← Back</button><button class="aus-btn red" onclick="openPizzaCart()">Pizza cart (${APP.cart.length})</button></div><section class="recovery-hero"><div class="recovery-brandlock"><div class="recovery-kicker">Australia Day · 26 January 2027 · Bali</div><div class="recovery-title">The Great<br>Aussie<br>Recovery</div><div class="recovery-tag">SAME SUN. LESS EFFORT.</div><div class="recovery-doodles"><span>☀️</span><span>🍕</span><span>〰️</span><span>🌴</span><span>🛟</span></div><p>Pizza · Pool · Triple J · Massages · Floaties</p></div></section>
<section class="section"><article class="card recovery-card"><div class="meta">Tuesday 26 January · From 10:00 AM</div><h3>The morning after the Big Bali Bash…</h3><p>Yesterday was the party. Today is pizza, pool, Triple J, massages and absolutely no pressure to do anything.</p><div class="pillrow three"><button class="aus-btn" onclick="openModal('recoveryItinerary')">Itinerary</button><a class="aus-btn yellow" href="https://www.abc.net.au/triplej/live/triplej" target="_blank" rel="noopener">Triple J</a><button class="aus-btn yellow" onclick="addCalendar('The Great Aussie Recovery','2027-01-26T10:00:00+08:00',600)">Calendar</button></div></article></section>
<section class="section"><div class="grid two"><article class="card recovery-card"><div class="meta">1:00–3:00 PM</div><h3>🍕 Bali Pizza Party</h3><p>Fresh pizza served at the villa as part of The Great Aussie Recovery.</p><div class="pillrow one"><button class="aus-btn red" onclick="openModal('pizzaInfo')">See details</button></div></article><article class="card recovery-card"><div class="meta">From 10:00 AM</div><h3>💆 Massage & Spa</h3><p>Choose your treatment and time. Four appointments are available in each 90-minute block.</p><div class="pillrow one"><button class="aus-btn" onclick="openModal('massage')">Book massage</button></div></article><article class="card recovery-card"><div class="meta">Pool day</div><h3>🛟 Float Hire</h3><p>Browse the supplier options, then book directly with Get Float Bali.</p><div class="pillrow one"><button class="aus-btn yellow" onclick="go('floats')">Choose your float</button></div></article></div></section></div></div>${navHtml()}`}
function pizzaMenuPage(){const section=(label,arr)=>`<div class="section"><div class="pizza-category">${label}</div><div class="pizza-grid">${arr.map(p=>`<article class="pizza-card"><div class="pizza-illustration">${p[2]}</div><div class="pizza-card-body"><h3>${p[0]}</h3><p>${p[1]}</p></div></article>`).join('')}</div></div>`;return `<div class="recovery-shell"><div class="shell"><button class="aus-btn" onclick="backTo('recovery')">← Back to Recovery</button><section class="pagehead" style="margin-top:20px;background:#fff6d8;border:2px solid var(--teal)"><div class="recovery-kicker">Bali Pizza Party</div><h1 style="color:var(--teal)">The Menu</h1><p>Here’s what’s firing up at the villa. This is included in the package — no menu pricing or add-to-cart buttons here.</p></section>${section('6 Classic Pizzas',PIZZAS.classic)}${section('2 Specialty Pizzas',PIZZAS.specialty)}${section('Something Sweet',PIZZAS.dessert)}<section class="section"><article class="card recovery-card"><h3>Good pizza · Good tunes · Good company</h3><p>The specialty selections will update here once they’re locked with the supplier.</p><div class="pillrow one"><button class="aus-btn" onclick="backTo('recovery')">← Back to Recovery</button></div></article></section></div></div>${navHtml()}`}
function floatsPage(){return `<div class="recovery-shell"><div class="shell"><button class="aus-btn" onclick="backTo('recovery')">← Back to Recovery</button><section class="pagehead" style="margin-top:20px;background:#fff6d8;border:2px solid var(--teal)"><div class="recovery-kicker">The Great Aussie Recovery</div><h1 style="color:var(--teal)">Choose Your Float</h1><p>Browse Get Float Bali’s range, then book directly with the supplier. No app cart or payment needed.</p></section><article class="card recovery-card"><h3>See the full current range</h3><p>The supplier catalogue changes, so the app sends you to Get Float Bali for the complete live selection, availability and booking.</p><div class="pillrow two"><a class="aus-btn yellow" href="${FLOAT_URL}" target="_blank" rel="noopener">Browse floaties</a><a class="aus-btn" href="https://wa.me/6282115157799" target="_blank" rel="noopener">WhatsApp supplier</a></div></article></div></div>${navHtml()}`}
function openModal(name){APP.modal=name;renderModal()}
function closeModal(){APP.modal=null;renderModal()}
function renderModal(){qsa('.overlay,.modal').forEach(el=>el.remove());if(!APP.modal)return;document.body.insertAdjacentHTML('beforeend','<div class="overlay" onclick="closeModal()"></div><div class="modal" role="dialog" aria-modal="true"><div class="modal-card" id="modalCard"></div></div>');const m=qs('#modalCard');if(!m)return;
  if(APP.modal==='sunset')m.innerHTML=`<div class="eyebrow">Sunday 24 January · From 4:00 PM</div><h2>Beanbags, Beers & Sunset</h2><img class="sunset-photo" src="assets/sunset-beach.png" alt="Beach beanbags at sunset in Bali"><p>The unofficial start to the Bali weekend. We’ll organise beachside beanbags, sunset drinks and an easy first catch-up. Totally optional — come for one drink or stay for sunset.</p><div class="pillrow three"><button class="btn olive" onclick="rsvpSunset()">I’m in</button><button class="btn light" onclick="addCalendar('Beanbags, Beers & Sunset','2027-01-24T16:00:00+08:00',180)">Add to calendar</button><button class="btn light" onclick="closeModal()">Close</button></div>`;
  if(APP.modal==='flights')m.innerHTML=flightFormHtml();
  if(APP.modal==='driver')m.innerHTML=driverFormHtml();
  if(APP.modal==='pizzaInfo')m.innerHTML=`<div class="eyebrow">Tuesday 26 January · 1:00–3:00 PM</div><h2>Bali Pizza Party 🍕</h2><p>Fresh pizza served at the villa as part of The Great Aussie Recovery.</p><div class="card" style="box-shadow:none;margin-top:18px"><div class="meta">What’s included</div><p>6 classic pizzas · 2 specialty pizzas · Nutella & fresh fruit dessert pizza.</p></div><div class="pillrow two"><button class="aus-btn red" onclick="closeModal();go('pizza-menu')">View the menu →</button><button class="aus-btn" onclick="openModal('pizzaBooking')">Book / pay</button></div><div class="pillrow one"><button class="aus-btn yellow" onclick="closeModal()">Back</button></div>`;
  if(APP.modal==='pizzaBooking')m.innerHTML=`<div class="eyebrow">Bali Pizza Party</div><h2>Book your spot</h2><p>Rp249,000 per person. This is the only item paid through Stripe in the app.</p><div class="field"><label>People</label><input id="pizzaQty" type="number" min="1" max="20" value="1"></div><div class="pillrow two"><button class="aus-btn red" onclick="addPizzaToCart()">Add to cart</button><button class="aus-btn" onclick="openModal('pizzaInfo')">Back</button></div>`;
  if(APP.modal==='massage'){m.classList.add('wide');m.innerHTML=massageHtml()}
  if(APP.modal==='recoveryItinerary')m.innerHTML=recoveryItineraryHtml();
  if(APP.modal==='cards')m.innerHTML=`<div class="travel-card-modal"><div class="eyebrow">Money in Bali</div><h2>Travel card options</h2><div class="grid two"><article class="card"><h3>Wise</h3><p>Multi-currency travel card and app.</p><a class="btn" target="_blank" rel="noopener" href="https://wise.com/au/travel-money/travel-money-card">Visit Wise</a></article><article class="card"><h3>Revolut</h3><p>Travel card and app for managing currencies.</p><a class="btn" target="_blank" rel="noopener" href="https://www.revolut.com/en-AU/travel/travel-money-card/">Visit Revolut</a></article></div><div class="pillrow one travel-card-close"><button class="btn light" onclick="closeModal()">Close</button></div></div>`;
  if(APP.modal==='visaHow')m.innerHTML=howToHtml('Visa / e-VOA',[['1. Choose the correct visa','For a short tourist stay, select the appropriate visitor visa for your circumstances on the official site.'],['2. Prepare your documents','Have your passport data page, photo and onward/return travel details ready where requested.'],['3. Enter details carefully','Check your name, passport number, dates and Indonesian address before submitting.'],['4. Pay and save your visa','After approval, keep a digital copy accessible on your phone.']]);
  if(APP.modal==='levyHow')m.innerHTML=howToHtml('Bali Tourist Levy',[['1. Open Love Bali','Use the official Love Bali website or app.'],['2. Enter your details','Provide the requested passport, name, email and arrival information.'],['3. Pay the levy','Complete payment through the official checkout.'],['4. Save the voucher','Keep the emailed voucher / QR code available for checkpoints.']]);
  if(APP.modal==='arrivalHow')m.innerHTML=howToHtml('All Indonesia',[['1. Open the official site','Use the official All Indonesia declaration site.'],['2. Complete traveller details','Enter the requested arrival, passport and declaration information carefully.'],['3. Submit in the permitted window','Complete it within the timeframe stated by the official service.'],['4. Save the QR code','Keep the confirmation accessible for arrival.']]);
}
function flightFormHtml(){const a=APP.flights.toBali||{},h=APP.flights.home||{};return `<div class="eyebrow">Your flights</div><h2>Arrival & departure</h2><div class="form"><h3 style="font-size:28px">Flight to Bali</h3>${flightFields('to',a,'PER','DPS')}<h3 style="font-size:28px;margin-top:10px">Flight home</h3>${flightFields('home',h,'DPS','PER')}<div class="pillrow two"><button class="btn olive" onclick="saveFlights()">Save flights</button><button class="btn light" onclick="closeModal()">Cancel</button></div></div>`}
function flightFields(prefix,f,fromDefault,toDefault){return `<div class="field"><label>Airline</label><input id="${prefix}Airline" value="${attr(f.airline||'')}" placeholder="Jetstar"></div><div class="field"><label>Flight number</label><input id="${prefix}No" value="${attr(f.no||'')}" placeholder="JQ116"></div><div class="grid two"><div class="field"><label>From</label><input id="${prefix}From" value="${attr(f.from||fromDefault)}"></div><div class="field"><label>To</label><input id="${prefix}To" value="${attr(f.to||toDefault)}"></div></div><div class="grid two"><div class="field"><label>Departure</label><input id="${prefix}Depart" type="datetime-local" value="${attr(f.depart||'')}"></div><div class="field"><label>Arrival</label><input id="${prefix}Arrive" type="datetime-local" value="${attr(f.arrive||'')}"></div></div>`}
function driverFormHtml(){const f=APP.flights.toBali||{};return `<div class="eyebrow">Airport pickup</div><h2>Book Made</h2><div class="driver-art">${driverSvg()}</div><p>Guaranteed pickup · Personalised sign · Great communication</p><div class="form"><div class="field"><label>Drop-off area</label><select id="driverArea" onchange="updateDriverTotal()"><option value="30">Kuta / Legian — $30 AUD</option><option value="40" selected>Seminyak — $40 AUD</option></select></div><div class="field"><label>Arrival flight</label><input id="driverFlight" value="${attr(f.airline&&f.no?`${f.airline} ${f.no}`:'')}" placeholder="Jetstar JQ..."></div><div class="field"><label>Arrival date & time</label><input id="driverArrival" type="datetime-local" value="${attr(f.arrive||'')}"></div><div class="field"><label>Personalised sign name</label><input id="driverSign" value="${attr(APP.profile.name||'')}" placeholder="Shannon"></div><div class="meta" style="margin-top:8px">Drinks waiting on arrival?</div><div class="drink-order">${drinkRow('Bintang',3,'bintang')}${drinkRow('Bintang Crystal',3,'crystal')}${drinkRow('Smirnoff Ice Lemon',4,'lemon')}${drinkRow('Smirnoff Ice Raspberry',4,'raspberry')}</div><div class="total-box"><span>Total due in cash</span><br><strong id="driverTotal">$40.00 AUD</strong><p style="margin:4px 0 0">Cash on delivery.</p></div><div class="pillrow two"><button class="btn olive" onclick="confirmDriver()">Confirm booking</button><button class="btn light" onclick="closeModal()">Cancel</button></div></div>`}
function drinkRow(name,price,id){return `<div><strong>${name}</strong><br><small>$${price}.00 AUD each</small></div><div class="qty"><button onclick="changeArrivalDrink('${id}',-1)">−</button><b id="driver-${id}">0</b><button onclick="changeArrivalDrink('${id}',1)">+</button></div>`}
function massageHtml(){return `<div class="eyebrow">The Great Aussie Recovery</div><h2>Book Massage</h2><p>Four appointments are available in each 90-minute block, from 10:00 AM through 5:30 PM. Payment is cash on the day.</p><div class="field"><label>Treatment</label><select id="massageTreatment">${MASSAGES.map(x=>`<option value="${x.id}">${x.name} · ${x.mins} min · ${money(x.price)}</option>`).join('')}</select></div><div class="field"><label>Time block</label><input id="massageSlot" type="hidden"><div class="slotgrid">${MASSAGE_SLOTS.map(s=>{const used=APP.bookings.filter(b=>b.slot===s&&b.status!=='cancelled').length;return `<button class="slot" onclick="selectMassageSlot(this,'${s}')"><b>${s}</b><span>${Math.max(0,4-used)} spots left</span></button>`}).join('')}</div></div><div class="pillrow two"><button class="aus-btn" onclick="confirmMassage()">Confirm · cash on day</button><button class="aus-btn yellow" onclick="closeModal()">Cancel</button></div>`}
function recoveryItineraryHtml(){const rows=[['10:00 AM','Massage & Spa Bookings Commence'],['11:00 AM','The Great Aussie Recovery Begins'],['11:00 AM','1:00 PM','Pool, Music, Drinks & Chill'],['1:00 PM','Bali Pizza Party Begins'],['1:00 PM','3:00 PM','Pizza Party'],['3:00 PM','Pizza Party Finishes'],['3:00 PM','4:00 PM','Pool, Triple J & Recovery Mode'],['4:00 PM','No Schedule']];return `<div class="eyebrow">Tuesday 26 January 2027</div><h2>The Itinerary</h2><div class="timeline recovery-itinerary">${rows.map(r=>{if(r.length===3)return `<div class="timeline-row"><div class="time range-time"><span>${r[0]}</span><small>to</small><span>${r[1]}</span></div><div><h4>${r[2]}</h4></div></div>`;return `<div class="timeline-row"><div class="time">${r[0]}</div><div><h4>${r[1]}</h4></div></div>`}).join('')}</div><div class="pillrow one"><button class="aus-btn" onclick="closeModal()">Close</button></div>`}
function howToHtml(title,steps){return `<div class="eyebrow">${title}</div><h2>How to apply</h2>${steps.map(s=>`<div class="card" style="box-shadow:none;margin-top:14px"><strong>${s[0]}</strong><p>${s[1]}</p></div>`).join('')}<div class="pillrow one"><button class="btn light" onclick="closeModal()">Close</button></div>`}
function changeDrink(id,delta){const el=qs(`#qty-${id}`);if(!el)return;el.textContent=String(Math.max(0,Number(el.textContent||0)+delta))}
function orderCocktails(){const items=COCKTAILS.map(c=>({c,qty:Number(qs(`#qty-${c.id}`)?.textContent||0)})).filter(x=>x.qty>0);if(!items.length)return toast('Choose a drink first');if(new Date()<new Date('2027-01-25T13:30:00+08:00'))return toast('Orders open at 1:30 PM on 25 Jan');const msg=`${APP.profile.name||'Guest'} has ordered ${items.map(x=>`${x.qty} x ${x.c.name}`).join(', ')}`;window.open(`https://wa.me/${CFG.cocktailWhatsApp}?text=${encodeURIComponent(msg)}`,'_blank')}
function rsvpSunset(){if(!APP.plans.some(p=>p.type==='sunset'))APP.plans.push({type:'sunset',title:'Beanbags, Beers & Sunset',meta:'24 Jan · From 4:00 PM',status:'Confirmed'});saveState();closeModal();toast('RSVP saved')}
function toggleReady(key,val){APP.check[key]=val;saveState();render()}
function choosePhotos(){const picker=qs('#photoPicker');if(!picker)return;picker.value='';picker.onchange=()=>{if(!picker.files.length)return;toast(`${picker.files.length} photo${picker.files.length===1?'':'s'} selected — opening Drive`);setTimeout(()=>window.open(DRIVE_URL,'_blank'),650)};picker.click()}
function chooseProfilePhoto(){const input=qs('#profilePhoto');if(!input)return;input.onchange=()=>toast(input.files?.length?'Photo ready — tap Save profile':'');input.click()}
function saveProfile(){const name=qs('#profileName')?.value.trim()||'';const email=qs('#profileEmail')?.value.trim()||'';const pin=qs('#profilePin')?.value.trim()||'';if(!name)return toast('Add your name');if(email&&!/^\S+@\S+\.\S+$/.test(email))return toast('Check your email address');if(pin&&!/^\d{4}$/.test(pin))return toast('PIN must be 4 digits');const input=qs('#profilePhoto');const file=input?.files?.[0];const done=photo=>{APP.profile={...APP.profile,name,email,pin,photo:photo||APP.profile.photo||''};saveState();render();toast('Profile saved')};if(!file)return done();const reader=new FileReader();reader.onload=()=>done(reader.result);reader.readAsDataURL(file)}
function planStatus(p){if(p.status)return p.status;if(p.pay==='cash')return 'Cash on day';if(p.pay==='paid')return 'Paid';return 'Confirmed'}
function cancelPlan(i){if(!confirm('Cancel this plan?'))return;const p=APP.plans[i];if(p?.bookingId){const b=APP.bookings.find(x=>x.id===p.bookingId);if(b)b.status='cancelled'}APP.plans.splice(i,1);saveState();render();toast('Cancelled')}
function saveFlights(){const read=prefix=>({airline:qs(`#${prefix}Airline`)?.value.trim()||'',no:qs(`#${prefix}No`)?.value.trim()||'',from:qs(`#${prefix}From`)?.value.trim().toUpperCase()||'',to:qs(`#${prefix}To`)?.value.trim().toUpperCase()||'',depart:qs(`#${prefix}Depart`)?.value||'',arrive:qs(`#${prefix}Arrive`)?.value||''});const to=read('to'),home=read('home');if(Object.values(to).some(v=>!v)||Object.values(home).some(v=>!v))return toast('Complete both flights');APP.flights={toBali:to,home};APP.check.flight=true;saveState();closeModal();render();toast('Flights saved')}
async function shareFlights(){const a=APP.flights.toBali,h=APP.flights.home;const text=[`${APP.profile.name||'Guest'}'s Bali flights ✈️`,a?`TO BALI: ${a.airline} ${a.no} · ${a.from} → ${a.to} · ${formatDateTime(a.depart)}`:'',h?`HOME: ${h.airline} ${h.no} · ${h.from} → ${h.to} · ${formatDateTime(h.depart)}`:''].filter(Boolean).join('\n');if(navigator.share){try{await navigator.share({title:'My Bali flights',text});return}catch{}}copyText(text)}
function changeArrivalDrink(id,delta){const el=qs(`#driver-${id}`);if(!el)return;el.textContent=String(Math.max(0,Number(el.textContent||0)+delta));updateDriverTotal()}
function driverBreakdown(){const area=Number(qs('#driverArea')?.value||40);const qty=id=>Number(qs(`#driver-${id}`)?.textContent||0);const drinks=[['Bintang',qty('bintang'),3],['Bintang Crystal',qty('crystal'),3],['Smirnoff Ice Lemon',qty('lemon'),4],['Smirnoff Ice Raspberry',qty('raspberry'),4]].filter(x=>x[1]>0);const drinkTotal=drinks.reduce((a,x)=>a+x[1]*x[2],0);return{area,drinks,total:area+drinkTotal}}
function updateDriverTotal(){const b=driverBreakdown();const el=qs('#driverTotal');if(el)el.textContent=money(b.total,'AUD')}
async function confirmDriver(){if(!APP.profile.email)return toast('Add your email in My Profile first');const flight=qs('#driverFlight')?.value.trim()||'';const arrival=qs('#driverArrival')?.value||'';const sign=qs('#driverSign')?.value.trim()||APP.profile.name||'Guest';if(!flight||!arrival)return toast('Add flight and arrival time');const b=driverBreakdown();const area=b.area===30?'Kuta / Legian':'Seminyak';const id=`driver-${Date.now()}`;const drinkText=b.drinks.length?b.drinks.map(x=>`${x[1]} x ${x[0]}`).join(', '):'No arrival drinks';const plan={id,type:'driver',title:`Airport pickup with Made`,meta:`${formatDateTime(arrival)} · ${area} · ${flight} · ${drinkText}`,status:'Cash on delivery',total:money(b.total,'AUD')};APP.plans.push(plan);saveState();const ok=await notifyAdmin('driver',{guest:APP.profile.name,email:APP.profile.email,flight,arrival,area,sign,drinks:drinkText,total:money(b.total,'AUD'),made:'+62 813-5302-1044'});closeModal();render();toast(ok?'Pickup saved · admin emailed':'Pickup saved · email service needs setup')}
function selectMassageSlot(btn,slot){qsa('.slot').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');const hidden=qs('#massageSlot');if(hidden)hidden.value=slot}
async function confirmMassage(){if(!APP.profile.email)return toast('Add your email in My Profile first');const id=qs('#massageTreatment')?.value;const slot=qs('#massageSlot')?.value;if(!slot)return toast('Choose a time');const used=APP.bookings.filter(b=>b.slot===slot&&b.status!=='cancelled').length;if(used>=4)return toast('That block is full');const t=MASSAGES.find(x=>x.id===id);if(!t)return toast('Choose a treatment');const bookingId=`massage-${Date.now()}`;APP.bookings.push({id:bookingId,slot,treatment:t.name,status:'booked'});APP.plans.push({bookingId,type:'massage',title:t.name,meta:`26 Jan · ${slot} · ${t.mins} min`,status:'Cash on the day',total:money(t.price)});saveState();const ok=await notifyAdmin('massage',{guest:APP.profile.name,email:APP.profile.email,treatment:t.name,slot,duration:`${t.mins} min`,price:money(t.price),payment:'Cash on the day'});closeModal();render();toast(ok?'Massage booked · confirmation sent':'Massage booked · email service needs setup')}
function addPizzaToCart(){if(!APP.profile.email)return toast('Add your email in My Profile first');const qty=Math.max(1,Number(qs('#pizzaQty')?.value||1));APP.cart=[{id:`pizza-${Date.now()}`,type:'pizza',title:`Bali Pizza Party × ${qty}`,qty,unitAmount:249000,currency:'IDR',meta:'26 Jan · 1:00–3:00 PM'}];saveState();closeModal();toast('Pizza added to cart')}
function openPizzaCart(){if(!APP.cart.length)return toast('Your pizza cart is empty');const item=APP.cart[0];const total=item.unitAmount*item.qty;document.body.insertAdjacentHTML('beforeend',`<div class="overlay cartOverlay" onclick="closeCart()"></div><div class="modal cartModal"><div class="modal-card"><div class="eyebrow">Pizza cart</div><h2>${esc(item.title)}</h2><p>${esc(item.meta)}</p><div class="total-box"><span>Total</span><br><strong>${money(total)}</strong></div><div class="pillrow two"><button class="aus-btn red" onclick="checkoutPizza()">Pay with Stripe</button><button class="aus-btn" onclick="closeCart()">Close</button></div></div></div>`)}
function closeCart(){qsa('.cartOverlay,.cartModal').forEach(x=>x.remove())}
async function checkoutPizza(){if(!APP.profile.email)return toast('Add your email first');const item=APP.cart[0];if(!item)return toast('Cart is empty');try{const res=await fetch('/api/create-checkout-session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({qty:item.qty,email:APP.profile.email,name:APP.profile.name})});const data=await res.json();if(!res.ok||!data.url)throw new Error(data.error||'Checkout unavailable');location.href=data.url}catch(err){console.error(err);toast('Stripe is not configured yet') }}
async function notifyAdmin(type,payload){try{const res=await fetch('/api/notify',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type,payload})});return res.ok}catch(err){console.warn('notify failed',err);return false}}
function openMaps(q){window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`,'_blank')}
function findNear(q){if(!navigator.geolocation)return openMaps(`${q} near Chandra Villas Seminyak`);navigator.geolocation.getCurrentPosition(p=>window.open(`https://www.google.com/maps/search/${encodeURIComponent(q)}/@${p.coords.latitude},${p.coords.longitude},15z`,'_blank'),()=>openMaps(`${q} near Chandra Villas Seminyak`),{timeout:5000})}
function copyText(t){navigator.clipboard?.writeText(t).then(()=>toast('Copied')).catch(()=>toast('Copy unavailable'))}
function addCalendar(title,start,duration=60){const s=new Date(start),e=new Date(s.getTime()+duration*60000),fmt=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const ics=`BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nDTSTART:${fmt(s)}\nDTEND:${fmt(e)}\nSUMMARY:${title}\nLOCATION:${CFG.address}\nEND:VEVENT\nEND:VCALENDAR`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([ics],{type:'text/calendar'}));a.download='bbb-bali.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function loadWeather(){const el=qs('#weather');if(!el)return;try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=-8.691&longitude=115.166&current=temperature_2m,relative_humidity_2m,precipitation&daily=temperature_2m_max,precipitation_probability_max&timezone=Asia%2FMakassar&forecast_days=7');if(!r.ok)throw new Error('weather');const d=await r.json();el.innerHTML=`<div class="meta">Live Seminyak weather</div><div class="weather-top"><div><div class="temp">${Math.round(d.current.temperature_2m)}°</div><p>${d.current.relative_humidity_2m}% humidity · ${d.current.precipitation}mm rain now</p></div><span class="tag">Bali time</span></div><div class="forecast">${d.daily.time.map((x,i)=>`<div>${new Date(`${x}T00:00:00`).toLocaleDateString(undefined,{weekday:'short'})}<b>${Math.round(d.daily.temperature_2m_max[i])}°</b><small>${d.daily.precipitation_probability_max[i]||0}% rain</small></div>`).join('')}</div>`}catch{el.innerHTML='<div class="meta">Live Seminyak weather</div><h3>Weather unavailable</h3><p>Try again when you have a connection.</p>'}}
async function loadFx(){const providers=[async()=>{const r=await fetch('https://open.er-api.com/v6/latest/AUD');if(!r.ok)throw new Error();const d=await r.json();return{rate:d.rates?.IDR,updated:d.time_last_update_utc}},async()=>{const r=await fetch('https://api.frankfurter.app/latest?from=AUD&to=IDR');if(!r.ok)throw new Error();const d=await r.json();return{rate:d.rates?.IDR,updated:d.date}}];for(const p of providers){try{const data=await p();if(!data.rate)continue;APP.fx=Number(data.rate);const rateEl=qs('#fxrate');if(rateEl)rateEl.textContent=`1 AUD = ${Math.round(APP.fx).toLocaleString()} IDR`;const updated=qs('#fxupdated');if(updated)updated.textContent=`Last updated: ${data.updated||'just now'}`;convertCurrency('aud');return}catch{}}const rateEl=qs('#fxrate');if(rateEl)rateEl.textContent='Live rate unavailable';const note=qs('#fxnote');if(note)note.textContent='Try again later. No conversion has been guessed.'}
function parseAmount(v){return Number(String(v||'').replace(/,/g,'').trim())||0}
function formatIdrValue(v){return Math.round(Number(v)||0).toLocaleString('en-AU')}
function convertCurrency(source){if(!APP.fx)return;const aud=qs('#aud'),idr=qs('#idr');if(!aud||!idr)return;if(source==='aud')idr.value=formatIdrValue(parseAmount(aud.value)*APP.fx);else aud.value=(parseAmount(idr.value)/APP.fx).toFixed(2)}
function swapCurrency(){if(!APP.fx)return toast('Live rate is still loading');const aud=qs('#aud'),idr=qs('#idr');if(!aud||!idr)return;const oldAud=parseAmount(aud.value),oldIdr=parseAmount(idr.value);aud.value=(oldIdr/APP.fx).toFixed(2);idr.value=formatIdrValue(oldAud*APP.fx)}
function driverSvg(){return `<svg viewBox="0 0 900 420" role="img" aria-label="Illustrated black and red Made airport transfer vehicle"><defs><linearGradient id="carBody" x1="0" x2="1"><stop offset="0" stop-color="#111719"/><stop offset=".55" stop-color="#252d30"/><stop offset="1" stop-color="#0d1113"/></linearGradient><linearGradient id="glass" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b9dfe8"/><stop offset="1" stop-color="#608896"/></linearGradient><filter id="shadow" x="-20%" y="-30%" width="140%" height="180%"><feDropShadow dx="0" dy="16" stdDeviation="12" flood-opacity=".22"/></filter></defs><ellipse cx="450" cy="342" rx="330" ry="34" fill="#7d6c58" opacity=".2"/><g filter="url(#shadow)"><path d="M132 188 C159 151 219 126 302 118 L487 110 C550 108 617 129 671 168 L751 225 C769 238 780 261 780 285 L780 307 L119 307 L119 231 C119 213 123 199 132 188Z" fill="url(#carBody)" stroke="#2e3537" stroke-width="5"/><path d="M281 126 L475 120 C528 119 582 136 629 168 L662 194 L252 194Z" fill="#151b1d"/><path d="M292 137 L397 133 L397 187 L267 187Z" fill="url(#glass)"/><path d="M409 132 L478 130 C526 129 566 141 606 166 L636 187 L409 187Z" fill="url(#glass)"/><path d="M162 203 H315 V301 H151 C133 301 124 291 124 276 V232 C124 215 136 203 162 203Z" fill="#b82f2d"/><path d="M607 197 H729 C753 197 770 215 770 238 V296 H607Z" fill="#b82f2d"/><rect x="326" y="203" width="266" height="98" rx="4" fill="#151a1c"/><path d="M327 205 V298 M458 204 V300 M594 205 V300" stroke="#4b5356" stroke-width="3"/><rect x="340" y="220" width="94" height="48" rx="9" fill="#cf3431"/><circle cx="387" cy="244" r="32" fill="#e34742"/><text x="387" y="240" text-anchor="middle" fill="white" font-size="18" font-family="Montserrat,Arial" font-weight="700">DARL'S</text><text x="387" y="258" text-anchor="middle" fill="white" font-size="13" font-family="Montserrat,Arial">BALI</text><text x="474" y="233" fill="#f7f1e6" font-size="17" font-family="Montserrat,Arial" font-weight="700">AIRPORT PICKUP</text><text x="474" y="257" fill="#cad4d6" font-size="13" font-family="Montserrat,Arial" letter-spacing="2">MADE · BALI</text><path d="M131 246 H159" stroke="#fff2bd" stroke-width="11" stroke-linecap="round"/><path d="M742 244 H772" stroke="#d83d34" stroke-width="12" stroke-linecap="round"/><circle cx="243" cy="306" r="70" fill="#0b0d0e" stroke="#303638" stroke-width="6"/><circle cx="243" cy="306" r="38" fill="#bfc5c6"/><circle cx="243" cy="306" r="14" fill="#4b5152"/><circle cx="650" cy="306" r="70" fill="#0b0d0e" stroke="#303638" stroke-width="6"/><circle cx="650" cy="306" r="38" fill="#bfc5c6"/><circle cx="650" cy="306" r="14" fill="#4b5152"/><path d="M151 307 H173 M313 307 H578 M720 307 H765" stroke="#111" stroke-width="8" stroke-linecap="round"/></g></svg>`}
function formatDateTime(v){if(!v)return'';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleString()}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function attr(s){return esc(s).replace(/`/g,'&#96;')}
function jsEsc(s){return String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'")}
function cocktailArt(id){const common=`<defs><filter id="s-${id}" x="-40%" y="-40%" width="180%" height="200%"><feDropShadow dx="0" dy="12" stdDeviation="10" flood-opacity=".16"/></filter><linearGradient id="g-${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#fff" stop-opacity=".7"/><stop offset="1" stop-color="#fff" stop-opacity=".05"/></linearGradient></defs>`;if(id==='berry')return `<svg viewBox="0 0 420 260" aria-label="Illustrated strawberry daiquiri">${common}<g filter="url(#s-${id})"><path d="M105 72 H306 C295 120 265 151 219 158 V211 H268 V221 H143 V211 H196 V158 C149 151 118 120 105 72Z" fill="#fff" fill-opacity=".55" stroke="#6b4e3d" stroke-width="4"/><path d="M115 82 H296 C282 120 257 139 207 146 C162 140 132 119 115 82Z" fill="#d85a54"/><path d="M121 88 H290" stroke="#f4b1a8" stroke-width="8" opacity=".7"/><path d="M270 62 c20-19 43-13 46 8 c2 20-13 35-35 28 c-16-5-23-22-11-36Z" fill="#d4473f" stroke="#6b4e3d" stroke-width="3"/><path d="M284 55 l-8-16 m13 16 l9-16 m-5 19 l18-7" stroke="#556b3f" stroke-width="5" stroke-linecap="round"/></g></svg>`;if(id==='mint')return `<svg viewBox="0 0 420 260" aria-label="Illustrated mojito">${common}<g filter="url(#s-${id})"><rect x="145" y="45" width="130" height="177" rx="22" fill="#fff" fill-opacity=".45" stroke="#6b4e3d" stroke-width="4"/><rect x="154" y="100" width="112" height="112" rx="15" fill="#dce8c9"/><g fill="#fff" opacity=".8"><rect x="168" y="111" width="29" height="25" rx="6" transform="rotate(-10 168 111)"/><rect x="210" y="120" width="31" height="28" rx="6" transform="rotate(8 210 120)"/></g><circle cx="184" cy="174" r="29" fill="#80a957" stroke="#556b3f" stroke-width="3"/><path d="M184 146 v56 M156 174 h56" stroke="#f7f1e6" stroke-width="3"/><path d="M190 101 C175 79 179 59 199 48 C207 70 203 91 190 101 M211 98 C208 75 221 58 242 58 C239 81 229 95 211 98 M172 102 C153 89 151 70 164 55 C179 72 182 91 172 102" fill="#5d8a44" stroke="#556b3f" stroke-width="2"/><path d="M248 49 L286 13" stroke="#c8a36f" stroke-width="5" stroke-linecap="round"/></g></svg>`;if(id==='after')return `<svg viewBox="0 0 420 260" aria-label="Illustrated espresso martini">${common}<g filter="url(#s-${id})"><path d="M100 62 H319 C300 112 266 147 221 154 V211 H272 V221 H148 V211 H199 V154 C153 147 119 112 100 62Z" fill="#fff" fill-opacity=".5" stroke="#6b4e3d" stroke-width="4"/><path d="M112 73 H307 C290 112 257 137 210 142 C166 137 132 112 112 73Z" fill="#3a2119"/><path d="M116 74 H303 C292 90 274 99 254 104 H165 C143 99 126 90 116 74Z" fill="#e7d7bd"/><g fill="#4d2a1f"><ellipse cx="192" cy="92" rx="9" ry="5" transform="rotate(-20 192 92)"/><ellipse cx="211" cy="88" rx="9" ry="5" transform="rotate(20 211 88)"/><ellipse cx="230" cy="94" rx="9" ry="5" transform="rotate(-10 230 94)"/></g></g></svg>`;if(id==='tropic')return `<svg viewBox="0 0 420 260" aria-label="Illustrated pina colada">${common}<g filter="url(#s-${id})"><path d="M155 47 C141 82 139 115 147 153 L163 220 H257 L273 153 C281 115 279 82 265 47Z" fill="#fff" fill-opacity=".52" stroke="#6b4e3d" stroke-width="4"/><path d="M154 90 H266 C271 120 268 149 260 194 H160 C151 149 149 121 154 90Z" fill="#f1dc9d"/><path d="M248 59 l40-40" stroke="#c8a36f" stroke-width="5" stroke-linecap="round"/><path d="M250 60 L287 38 L301 73 L274 91Z" fill="#e7b849" stroke="#6b4e3d" stroke-width="3"/><path d="M285 38 l10-18 m-3 20 l22-8" stroke="#556b3f" stroke-width="5" stroke-linecap="round"/><path d="M162 95 C145 82 142 64 153 51 C169 65 174 83 162 95 M180 89 C177 66 190 50 211 50 C208 73 197 87 180 89" fill="#5f7c47"/></g></svg>`;return `<svg viewBox="0 0 420 260" aria-label="Illustrated mini beer shots">${common}<g filter="url(#s-${id})"><g transform="translate(60 0)"><path d="M70 95 H137 V192 C137 205 127 216 114 216 H93 C80 216 70 205 70 192Z" fill="#f0ae2c" stroke="#6b4e3d" stroke-width="4"/><path d="M73 95 H134 V120 H73Z" fill="#f7f1e6"/><path d="M166 80 H233 V192 C233 205 223 216 210 216 H189 C176 216 166 205 166 192Z" fill="#e7a426" stroke="#6b4e3d" stroke-width="4"/><path d="M169 80 H230 V108 H169Z" fill="#f7f1e6"/><path d="M118 116 H157 C171 116 180 127 180 141 C180 155 171 166 157 166 H137" fill="none" stroke="#6b4e3d" stroke-width="4"/><path d="M214 109 H254 C268 109 277 120 277 134 C277 149 268 160 254 160 H233" fill="none" stroke="#6b4e3d" stroke-width="4"/></g></g></svg>`}
function cartPage(){const item=APP.cart[0];const q=item?Number(item.qty)||1:0;const total=item?item.unitAmount*q:0;return `<div class="shell page-route">${headerHtml()}<section class="pagehead"><div class="eyebrow">Your cart</div><h1>Checkout</h1><p>Only the Bali Pizza Party is paid through the app.</p></section>${item?`<article class="card checkout-card"><div class="meta">Your order</div><h3>Bali Pizza Party</h3><p>${esc(item.meta)} · ${q} ${q===1?'person':'people'}</p><div class="cart-line"><span>${q} × ${money(item.unitAmount)}</span><strong>${money(total)}</strong></div><div class="payment-note"><div class="meta">Payment information</div><p>Your payment is processed securely through Stripe and will go to <strong>Nicolle</strong>, who will use it to organise your Bali Pizza Party booking on your behalf.</p></div><button class="btn olive full stripe-pay" onclick="checkoutPizza()">Pay securely with Stripe</button><p class="checkout-fine">Once Stripe confirms payment, the booking is added to My Plans and your Stripe receipt is sent to the email on your profile.</p><button class="btn light full" onclick="backTo('recovery')">← Continue browsing</button></article>`:`<article class="card"><div class="meta">Cart</div><h3>Your cart is empty</h3><p>The Bali Pizza Party is the only app purchase. Massage is cash on the day and floaties are booked directly with the supplier.</p><div class="pillrow one"><button class="btn olive" onclick="go('recovery')">Go to The Great Aussie Recovery</button></div></article>`}</div>${navHtml()}`}
function openPizzaCart(){go('cart')}
function processStripeReturn(){const p=new URLSearchParams(location.search);if(p.get('paid')==='1'&&APP.cart.length){const item=APP.cart[0];APP.plans.push({type:'pizza',title:item.title,meta:item.meta,status:'Paid online via Stripe',total:money(item.unitAmount*item.qty)});APP.cart=[];saveState();history.replaceState({},'',location.pathname+location.hash);toast('Pizza payment successful') }}
function render(){const app=qs('#app');if(!app)return;try{const r=APP.route;if(r==='home')app.innerHTML=homePage();else if(r==='bbb')app.innerHTML=bbbPage();else if(r==='travel')app.innerHTML=travelPage();else if(r==='ready')app.innerHTML=readyPage();else if(r==='bali')app.innerHTML=baliPage();else if(r==='profile')app.innerHTML=profilePage();else if(r==='recovery')app.innerHTML=recoveryPage();else if(r==='pizza-menu')app.innerHTML=pizzaMenuPage();else if(r==='floats')app.innerHTML=floatsPage();else if(r==='cart')app.innerHTML=cartPage();else if(r.startsWith('guide-'))app.innerHTML=guidePage(Number(r.split('-')[1]));else{APP.route='home';app.innerHTML=homePage()}renderModal();if(APP.route==='bali')setTimeout(()=>{loadWeather();loadFx()},20)}catch(err){console.error(err);app.innerHTML='<div class="shell"><article class="card"><h3>App loading issue</h3><p>Please refresh. The error has been logged in the browser console.</p></article></div>'}}
window.addEventListener('error',e=>console.error('App error:',e.error||e.message));
window.addEventListener('unhandledrejection',e=>console.error('Promise error:',e.reason));
setInterval(()=>{const c=qs('#countdown');if(c)c.innerHTML=countdownHtml()},1000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>{});
processStripeReturn();render();
